1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir> [--bundle]
7	//   policy-sign --policy <policy.json> --key <private.pem> --signature <policy.json.sig>
8	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
9	//            [--sbom <file> --sbom-signature <file>] [--policy <policy.json>]
10	//            [--policy-signature <policy.json.sig> --policy-key <public.pem>]
11	//   verify   --artifact <path> --bundle <proof.bundle.json> --key <public-key>
12	//            [--cosigner-key <public-key> ... --min-cosigners <n>] [--policy <policy.json>]
13	//            [--policy-signature <policy.json.sig> --policy-key <public.pem>]
14	//
15	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
16	
17	import {
18	  createHash,
19	  createPrivateKey,
20	  createPublicKey,
21	  generateKeyPairSync,
22	  sign as cryptoSign,
23	  verify as cryptoVerify,
24	} from 'node:crypto';
25	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
26	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
27	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
28	import { fileURLToPath } from 'node:url';
29	
30	export const PROOF_VERSION = '1.0';
31	// 启用多方共签时证明版本升为 1.1；共签清单（proof/sbom.cosignatures.json）的 schemaVersion。
32	export const PROOF_VERSION_COSIGN = '1.1';
33	export const COSIGN_SCHEMA_VERSION = '1.0';
34	// 证明分发包（proof.bundle.json）版本与成员逻辑名。
35	export const BUNDLE_VERSION = '1.0';
36	export const BUNDLE_BASE_MEMBERS = Object.freeze(['proof', 'proof-signature', 'sbom', 'sbom-signature']);
37	export const BUNDLE_COSIGN_MEMBERS = Object.freeze(['proof-cosignatures', 'sbom-cosignatures']);
38	
39	// ---------------------------------------------------------------------------
40	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
41	// ---------------------------------------------------------------------------
42	
43	export const ERROR_CODES = Object.freeze({
44	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
45	  PERMISSION_DENIED: 'PERMISSION_DENIED',
46	  PROOF_INVALID: 'PROOF_INVALID',
47	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
48	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
49	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
50	  POLICY_INVALID: 'POLICY_INVALID',
51	  POLICY_VIOLATION: 'POLICY_VIOLATION',
52	  SYMLINK_INVALID: 'SYMLINK_INVALID',
53	  USAGE_ERROR: 'USAGE_ERROR',
54	});
55	
56	class ProvError extends Error {
57	  constructor(code, message, details) {
58	    super(message);
59	    this.name = 'ProvError';
60	    this.code = code;
61	    if (details !== undefined) this.details = details;
62	  }
63	}
64	
65	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
66	function wrapFsError(err, context) {
67	  if (err instanceof ProvError) return err;
68	  const where = context ? `${context}: ` : '';
69	  if (err && err.code === 'ENOENT') {
70	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
71	  }
72	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
73	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
74	  }
75	  return err;
76	}
77	
78	// ---------------------------------------------------------------------------
79	// 路径与摘要工具
80	// ---------------------------------------------------------------------------
81	
82	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
83	export function toPosix(relPath) {
84	  return relPath.split(sep).join('/');
85	}
86	
87	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
88	export function stableJsonStringify(value) {
89	  return JSON.stringify(sortDeep(value), null, 2);
90	}
91	
92	function sortDeep(value) {
93	  if (Array.isArray(value)) return value.map(sortDeep);
94	  if (value !== null && typeof value === 'object') {
95	    const out = {};
96	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
97	    return out;
98	  }
99	  return value;
100	}
101	
102	export function sha256Hex(data) {
103	  return createHash('sha256').update(data).digest('hex');
104	}
105	
106	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
107	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
108	export function keyFingerprint(keyObj) {
109	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
110	}
111	
112	// ---------------------------------------------------------------------------
113	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
114	// 空目录自然产生空清单；零字节文件按真实文件记录。
115	// 符号链接安全规则（按真实路径判定）：
116	//   - 目标越出产物根目录                 -> SYMLINK_INVALID / outside-root；
117	//   - 目标为当前递归祖先链上的目录（含根目录自身），或链接互相成环（ELOOP）
118	//                                        -> SYMLINK_INVALID / cycle；
119	//   - 指向根目录内部普通文件/目录的链接按链接路径记录目标内容；
120	//     祖先链之外的重复目标允许展开（有向无环，不会形成回路）。
121	// 判定在读取目标内容之前完成，危险链接不会被解引用读取。
122	// ---------------------------------------------------------------------------
123	
124	// 符号链接安全检查失败：携带相对路径与原因（cycle / outside-root）。
125	function symlinkError(fullPath, rootDir, reason) {
126	  const relPath = toPosix(relative(rootDir, fullPath));
127	  const message =
128	    reason === 'cycle'
129	      ? `符号链接形成回路: ${relPath}`
130	      : `符号链接越出产物根目录: ${relPath}`;
131	  return new ProvError(ERROR_CODES.SYMLINK_INVALID, message, { path: relPath, reason });
132	}
133	
134	// 解析真实路径；底层错误按既有归类转换。
135	async function realPathOf(p, context) {
136	  try {
137	    return await realpath(p);
138	  } catch (err) {
139	    throw wrapFsError(err, context);
140	  }
141	}
142	
143	async function walkFiles(rootDir) {
144	  const found = [];
145	  const rootReal = await realPathOf(rootDir, '读取产物目录');
146	  // chain 为当前递归路径上各级目录的真实路径，用于识别指回祖先的链接回路。
147	  async function walk(dir, chain) {
148	    let entries;
149	    try {
150	      entries = await readdir(dir, { withFileTypes: true });
151	    } catch (err) {
152	      throw wrapFsError(err, '读取产物目录');
153	    }
154	    for (const entry of entries) {
155	      const full = join(dir, entry.name);
156	      if (entry.isDirectory()) {
157	        await walk(full, [...chain, await realPathOf(full, '读取产物目录')]);
158	      } else if (entry.isFile()) {
159	        found.push(full);
160	      } else if (entry.isSymbolicLink()) {
161	        // 先解析真实目标并做安全判定，再按目标类型处理：
162	        // 指向目录则继续递归，指向文件则按链接路径记录。
163	        let targetReal;
164	        try {
165	          targetReal = await realpath(full);
166	        } catch (err) {
167	          // 链接互相指向成环（如 a -> b、b -> a）时 realpath 报 ELOOP。
168	          if (err && err.code === 'ELOOP') throw symlinkError(full, rootDir, 'cycle');
169	          throw wrapFsError(err, '读取符号链接');
170	        }
171	        if (!isWithin(targetReal, rootReal)) {
172	          throw symlinkError(full, rootDir, 'outside-root');
173	        }
174	        if (chain.includes(targetReal)) {
175	          throw symlinkError(full, rootDir, 'cycle');
176	        }
177	        let target;
178	        try {
179	          target = await stat(full);
180	        } catch (err) {
181	          throw wrapFsError(err, '读取符号链接');
182	        }
183	        if (target.isDirectory()) await walk(full, [...chain, targetReal]);
184	        else if (target.isFile()) found.push(full);
185	      }
186	      // 其他特殊文件（套接字/设备等）忽略。
187	    }
188	  }
189	  await walk(rootDir, [rootReal]);
190	  return found;
191	}
192	
193	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
194	function isWithin(pathAbs, dirAbs) {
195	  const relPath = relative(dirAbs, pathAbs);
196	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
197	}
198	
199	async function fileTypeFromPath(fullPath, data) {
200	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
201	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
202	  const startsWith = (bytes) =>
203	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
204	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
205	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
206	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
207	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
208	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
209	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
210	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
211	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
212	  if (
213	    startsWith([0xef, 0xbb, 0xbf]) ||
214	    startsWith([0xff, 0xfe]) ||
215	    startsWith([0xfe, 0xff])
216	  ) {
217	    return 'text/plain';
218	  }
219	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
220	  const ext = basename(fullPath).split('.').pop();
221	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
222	}
223	
224	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
225	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
226	export async function buildSbom(artifactPath, excludeDir) {
227	  const artifactAbs = resolve(artifactPath);
228	  let artifactStat;
229	  try {
230	    artifactStat = await stat(artifactAbs);
231	  } catch (err) {
232	    throw wrapFsError(err, '读取产物');
233	  }
234	
235	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
236	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
237	
238	  let files;
239	  if (artifactStat.isDirectory()) {
240	    files = await walkFiles(artifactAbs);
241	  } else {
242	    files = [artifactAbs];
243	  }
244	
245	  const entries = [];
246	  for (const full of files) {
247	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
248	    let data;
249	    try {
250	      data = await readFile(full);
251	    } catch (err) {
252	      throw wrapFsError(err, '读取产物文件');
253	    }
254	    const relPath = toPosix(relative(rootDir, full));
255	    entries.push({
256	      path: relPath,
257	      sha256: sha256Hex(data),
258	      size: data.length,
259	      type: await fileTypeFromPath(full, data),
260	    });
261	  }
262	
263	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
264	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
265	
266	  return {
267	    schemaVersion: '1.0',
268	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
269	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
270	    files: entries,
271	  };
272	}
273	
274	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
275	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
276	export function computeArtifactDigest(sbom) {
277	  return sha256Hex(stableJsonStringify(sbom.files));
278	}
279	
280	// ---------------------------------------------------------------------------
281	// 密钥与签名（Ed25519，PEM）
282	// ---------------------------------------------------------------------------
283	
284	function readPrivateKey(keyPath) {
285	  let pem;
286	  try {
287	    pem = readFileSync(keyPath);
288	  } catch (err) {
289	    throw wrapFsError(err, '读取私钥');
290	  }
291	  let keyObj;
292	  try {
293	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
294	  } catch {
295	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
296	  }
297	  if (keyObj.asymmetricKeyType !== 'ed25519') {
298	    throw new ProvError(
299	      ERROR_CODES.KEY_NOT_FOUND,
300	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
301	    );
302	  }
303	  return keyObj;
304	}
305	
306	function readPublicKey(keyPath) {
307	  let pem;
308	  try {
309	    pem = readFileSync(keyPath);
310	  } catch (err) {
311	    throw wrapFsError(err, '读取公钥');
312	  }
313	  let keyObj;
314	  try {
315	    keyObj = createPublicKey({ key: pem, format: 'pem' });
316	  } catch {
317	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
318	  }
319	  if (keyObj.asymmetricKeyType !== 'ed25519') {
320	    throw new ProvError(
321	      ERROR_CODES.KEY_NOT_FOUND,
322	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
323	    );
324	  }
325	  return keyObj;
326	}
327	
328	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
329	function nowIso() {
330	  return new Date().toISOString();
331	}
332	
333	// ---------------------------------------------------------------------------
334	// keygen
335	// ---------------------------------------------------------------------------
336	
337	export async function keygen({ keyDir, name = 'provguard' }) {
338	  const absDir = resolve(keyDir);
339	  try {
340	    await mkdir(absDir, { recursive: true });
341	  } catch (err) {
342	    throw wrapFsError(err, '创建密钥目录');
343	  }
344	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
345	  const privPath = join(absDir, `${name}.private.pem`);
346	  const pubPath = join(absDir, `${name}.public.pem`);
347	  try {
348	    await writeFile(
349	      privPath,
350	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
351	      { mode: 0o600 },
352	    );
353	    await writeFile(
354	      pubPath,
355	      publicKey.export({ type: 'spki', format: 'pem' }),
356	      { mode: 0o644 },
357	    );
358	  } catch (err) {
359	    throw wrapFsError(err, '写入密钥');
360	  }
361	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
362	}
363	
364	// ---------------------------------------------------------------------------
365	// generate
366	// ---------------------------------------------------------------------------
367	
368	export async function generate({ artifact, key, out, coKeys = [], bundle = false }) {
369	  // 输入检查：产物与私钥必须存在且可读。
370	  const artifactAbs = resolve(artifact);
371	  const keyAbs = resolve(key);
372	  const coSign = coKeys.length > 0;
373	  const coKeyAbsList = coKeys.map((p) => resolve(p));
374	  const inputs = [
375	    [artifactAbs, '产物'],
376	    [keyAbs, '私钥'],
377	  ];
378	  for (const p of coKeyAbsList) inputs.push([p, '共签私钥']);
379	  for (const [p, label] of inputs) {
380	    try {
381	      await access(p, fsConstants.R_OK);
382	    } catch (err) {
383	      throw wrapFsError(err, `读取${label}`);
384	    }
385	  }
386	
387	  const outAbs = resolve(out);
388	  const parent = dirname(outAbs);
389	  try {
390	    await mkdir(parent, { recursive: true });
391	  } catch (err) {
392	    throw wrapFsError(err, '创建输出目录');
393	  }
394	
395	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
396	  try {
397	    await mkdir(outAbs, { recursive: true });
398	  } catch (err) {
399	    throw wrapFsError(err, '创建输出目录');
400	  }
401	  let outReal;
402	  try {
403	    outReal = await realpath(outAbs);
404	  } catch (err) {
405	    throw wrapFsError(err, '解析输出目录');
406	  }
407	
408	  const privateKey = readPrivateKey(keyAbs);
409	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
410	  const signingPublicKey = createPublicKey(privateKey);
411	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
412	
413	  // 共签私钥：逐一读取并校验为 Ed25519；指纹不得重复，也不得与主签名密钥相同，
414	  // 否则为 USAGE_ERROR。共签者按指纹升序排列，保证输出确定。
415	  const coSigners = [];
416	  if (coSign) {
417	    const seen = new Set([signerKeyFingerprint.toLowerCase()]);
418	    for (const p of coKeyAbsList) {
419	      const coKey = readPrivateKey(p);
420	      const fingerprint = keyFingerprint(createPublicKey(coKey));
421	      if (seen.has(fingerprint.toLowerCase())) {
422	        throw new ProvError(
423	          ERROR_CODES.USAGE_ERROR,
424	          '共签私钥重复或与主密钥相同（--co-key 必须互不相同且不同于 --key）',
425	        );
426	      }
427	      seen.add(fingerprint.toLowerCase());
428	      coSigners.push({ key: coKey, fingerprint });
429	    }
430	    coSigners.sort((a, b) => (a.fingerprint < b.fingerprint ? -1 : a.fingerprint > b.fingerprint ? 1 : 0));
431	  }
432	
433	  const sbom = await buildSbom(artifactAbs, outReal);
434	  const artifactDigest = computeArtifactDigest(sbom);
435	
436	  // SBOM 规范字节：稳定 JSON（去尾换行后的 UTF-8）。proof 中的 sbomDigest 与
437	  // sbom.json.sig 绑定同一组字节，防止证明有效而 sbom.json 被整体替换。
438	  const sbomCanonical = stableJsonStringify(sbom);
439	  const sbomDigest = sha256Hex(sbomCanonical);
440	
441	  const proof = {
442	    proofVersion: coSign ? PROOF_VERSION_COSIGN : PROOF_VERSION,
443	    artifactName: basename(artifactAbs),
444	    artifactDigest,
445	    fileName: basename(artifactAbs),
446	    size: sbom.files.reduce((n, f) => n + f.size, 0),
447	    generatedAt: nowIso(),
448	    signerKeyFingerprint,
449	    sbomDigest,
450	    files: sbom.files,
451	  };
452	  // 启用共签时证明声明共签者集合（按指纹升序、已去重），随证明一起被主签名保护。
453	  if (coSign) {
454	    proof.cosignerKeyFingerprints = coSigners.map((c) => c.fingerprint);
455	  }
456	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
457	  const proofJson = stableJsonStringify(proof) + '\n';
458	  const sbomJson = sbomCanonical + '\n';
459	
460	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
461	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
462	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
463	  const signatureB64 = signature.toString('base64') + '\n';
464	  // 对 SBOM 规范字节单独签名，Base64 加换行保存。
465	  const sbomSignature = cryptoSign(null, Buffer.from(sbomCanonical, 'utf8'), privateKey);
466	  const sbomSignatureB64 = sbomSignature.toString('base64') + '\n';
467	
468	  const proofPath = join(outReal, 'proof.json');
469	  const sbomPath = join(outReal, 'sbom.json');
470	  const sigPath = join(outReal, 'proof.json.sig');
471	  const sbomSigPath = join(outReal, 'sbom.json.sig');
472	  // 共签清单：每个共签者对与主签名相同的证明规范字节签名（proof.cosignatures.json），
473	  // 并另对 SBOM 规范字节签名（sbom.cosignatures.json）。不提供 --co-key 时不创建这些文件。
474	  const proofCosigPath = coSign ? join(outReal, 'proof.cosignatures.json') : null;
475	  const sbomCosigPath = coSign ? join(outReal, 'sbom.cosignatures.json') : null;
476	  // 证明分发包：--bundle 时在输出目录额外写出 proof.bundle.json（不影响既有文件）。
477	  const bundlePath = bundle ? join(outReal, 'proof.bundle.json') : null;
478	  try {
479	    await atomicWrite(proofPath, proofJson);
480	    await atomicWrite(sbomPath, sbomJson);
481	    await atomicWrite(sigPath, signatureB64);
482	    await atomicWrite(sbomSigPath, sbomSignatureB64);
483	    let proofCosigJson = null;
484	    let sbomCosigJson = null;
485	    if (coSign) {
486	      const proofBytes = Buffer.from(proofJson.trimEnd(), 'utf8');
487	      const sbomBytes = Buffer.from(sbomCanonical, 'utf8');
488	      const cosignManifest = (bytes) => ({
489	        schemaVersion: COSIGN_SCHEMA_VERSION,
490	        artifactDigest,
491	        sbomDigest,
492	        signers: coSigners.map((c) => ({
493	          keyFingerprint: c.fingerprint,
494	          signature: cryptoSign(null, bytes, c.key).toString('base64'),
495	        })),
496	      });
497	      proofCosigJson = stableJsonStringify(cosignManifest(proofBytes)) + '\n';
498	      sbomCosigJson = stableJsonStringify(cosignManifest(sbomBytes)) + '\n';
499	      await atomicWrite(proofCosigPath, proofCosigJson);
500	      await atomicWrite(sbomCosigPath, sbomCosigJson);
501	    }
502	    if (bundle) {
503	      const entries = [
504	        ['proof', proofJson],
505	        ['proof-signature', signatureB64],
506	        ['sbom', sbomJson],
507	        ['sbom-signature', sbomSignatureB64],
508	      ];
509	      if (coSign) {
510	        entries.push(['proof-cosignatures', proofCosigJson], ['sbom-cosignatures', sbomCosigJson]);
511	      }
512	      await atomicWrite(bundlePath, buildBundleJson(entries));
513	    }
514	  } catch (err) {
515	    throw wrapFsError(err, '写入证明产物');
516	  }
517	
518	  const result = {
519	    proofPath,
520	    sbomPath,
521	    signaturePath: sigPath,
522	    sbomSignaturePath: sbomSigPath,
523	    artifactDigest,
524	    sbomDigest,
525	    fileCount: sbom.files.length,
526	    proofVersion: proof.proofVersion,
527	  };
528	  if (coSign) {
529	    result.cosignerCount = coSigners.length;
530	    result.proofCosignaturesPath = proofCosigPath;
531	    result.sbomCosignaturesPath = sbomCosigPath;
532	  }
533	  if (bundle) {
534	    result.bundlePath = bundlePath;
535	  }
536	  return result;
537	}
