539	// ---------------------------------------------------------------------------
540	// policy-sign：为既有策略文件生成独立的 Ed25519 签名。
541	// 不改写策略、私钥或任何证明产物；签名覆盖 policy.json 的 UTF-8 稳定 JSON
542	// 字节（键名排序、两空格缩进、末尾换行），Base64 加换行保存，重复生成逐字节一致。
543	// 校验顺序：策略与私钥可读 -> 策略 JSON 合法（POLICY_INVALID）-> 私钥可解析且为
544	// Ed25519（KEY_NOT_FOUND）-> 写签名（写失败 PERMISSION_DENIED）。
545	// ---------------------------------------------------------------------------
546	
547	export async function policySign({ policy: policyPath, key: keyPath, signature: sigPath }) {
548	  const policyAbs = resolve(policyPath);
549	  const keyAbs = resolve(keyPath);
550	  const sigAbs = resolve(sigPath);
551	  // 输入检查：策略与私钥必须存在且可读。
552	  for (const [p, label] of [
553	    [policyAbs, '策略文件'],
554	    [keyAbs, '私钥'],
555	  ]) {
556	    try {
557	      await access(p, fsConstants.R_OK);
558	    } catch (err) {
559	      throw wrapFsError(err, `读取${label}`);
560	    }
561	  }
562	
563	  // 以磁盘字节为真解析并校验策略结构，再重算稳定 JSON 字节作为签名输入。
564	  let policyText;
565	  try {
566	    policyText = await readFileUtf8(policyAbs);
567	  } catch (err) {
568	    throw wrapFsError(err, '读取策略文件');
569	  }
570	  let policy;
571	  try {
572	    policy = JSON.parse(policyText);
573	  } catch {
574	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略文件不是合法的 JSON');
575	  }
576	  // 复用既有严格校验：未知字段、取值与 policyVersion 非法均为 POLICY_INVALID。
577	  const policyError = validatePolicyObject(policy);
578	  if (policyError) {
579	    throw new ProvError(ERROR_CODES.POLICY_INVALID, policyError);
580	  }
581	
582	  const privateKey = readPrivateKey(keyAbs);
583	  const signerFingerprint = keyFingerprint(createPublicKey(privateKey));
584	
585	  const canonicalBytes = Buffer.from(stableJsonStringify(policy) + '\n', 'utf8');
586	  const signatureB64 = cryptoSign(null, canonicalBytes, privateKey).toString('base64') + '\n';
587	  try {
588	    await atomicWrite(sigAbs, signatureB64);
589	  } catch (err) {
590	    throw wrapFsError(err, '写入策略签名文件');
591	  }
592	
593	  return {
594	    policyPath: policyAbs,
595	    signaturePath: sigAbs,
596	    policySignerFingerprint: signerFingerprint,
597	  };
598	}
599	
600	// ---------------------------------------------------------------------------
601	// 证明分发包（proof.bundle.json）：把一套证明产物打包为单个稳定 JSON 文件。
602	// members 按逻辑名排序（stableJsonStringify 按键名排序），每项保存原文件字节的
603	// Base64、SHA-256 与字节长度；原样保留文件字节（含签名输入的规范字节），
604	// 因此除 generatedAt、proof 及其签名外，重复生成的包内容逐字节稳定。
605	// ---------------------------------------------------------------------------
606	
607	function bundleMember(content) {
608	  const buf = Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf8');
609	  return { data: buf.toString('base64'), sha256: sha256Hex(buf), size: buf.length };
610	}
611	
612	function buildBundleJson(entries) {
613	  const members = {};
614	  for (const [name, content] of entries) members[name] = bundleMember(content);
615	  return stableJsonStringify({ bundleVersion: BUNDLE_VERSION, members }) + '\n';
616	}
617	
618	// 解析并校验分发包结构，返回 { members: Map<逻辑名, Buffer>, hasCosignMembers }。
619	// JSON 不可解析、bundleVersion 非 1.0、成员缺失或多余、Base64 非法、
620	// 长度或 SHA-256 不符均为 PROOF_INVALID。
621	function parseBundle(text) {
622	  let bundle;
623	  try {
624	    bundle = JSON.parse(text);
625	  } catch {
626	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明分发包不是合法的 JSON');
627	  }
628	  if (bundle === null || typeof bundle !== 'object' || Array.isArray(bundle)) {
629	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明分发包顶层必须是 JSON 对象');
630	  }
631	  if (bundle.bundleVersion !== BUNDLE_VERSION) {
632	    throw new ProvError(
633	      ERROR_CODES.PROOF_INVALID,
634	      `分发包 bundleVersion 缺失或不受支持（应为 ${BUNDLE_VERSION}）`,
635	    );
636	  }
637	  const rawMembers = bundle.members;
638	  if (rawMembers === null || typeof rawMembers !== 'object' || Array.isArray(rawMembers)) {
639	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '分发包字段缺失或类型非法: members');
640	  }
641	  const known = new Set([...BUNDLE_BASE_MEMBERS, ...BUNDLE_COSIGN_MEMBERS]);
642	  for (const name of Object.keys(rawMembers)) {
643	    if (!known.has(name)) {
644	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `分发包含有多余成员: ${name}`);
645	    }
646	  }
647	  for (const name of BUNDLE_BASE_MEMBERS) {
648	    if (!(name in rawMembers)) {
649	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `分发包缺少成员: ${name}`);
650	    }
651	  }
652	  // 共签成员必须成对出现（与生成时的输出一致）。
653	  const hasProofCosig = BUNDLE_COSIGN_MEMBERS[0] in rawMembers;
654	  const hasSbomCosig = BUNDLE_COSIGN_MEMBERS[1] in rawMembers;
655	  if (hasProofCosig !== hasSbomCosig) {
656	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '分发包共签成员必须成对出现');
657	  }
658	  const members = new Map();
659	  for (const [name, m] of Object.entries(rawMembers)) {
660	    members.set(name, decodeBundleMember(name, m));
661	  }
662	  return { members, hasCosignMembers: hasProofCosig };
663	}
664	
665	function decodeBundleMember(name, member) {
666	  const bad = (why) => new ProvError(ERROR_CODES.PROOF_INVALID, `分发包成员 ${name} ${why}`);
667	  if (member === null || typeof member !== 'object' || Array.isArray(member)) {
668	    throw bad('必须是对象');
669	  }
670	  if (typeof member.data !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(member.data)) {
671	    throw bad('的 data 不是合法的 Base64 内容');
672	  }
673	  if (typeof member.sha256 !== 'string' || !/^[0-9a-f]{64}$/i.test(member.sha256)) {
674	    throw bad('的 sha256 不是合法的 SHA-256 十六进制摘要');
675	  }
676	  if (!isNonNegSafeInt(member.size)) {
677	    throw bad('的 size 非法（应为非负安全整数）');
678	  }
679	  const buf = Buffer.from(member.data, 'base64');
680	  if (buf.length !== member.size) {
681	    throw bad('的字节长度与 size 不符');
682	  }
683	  if (sha256Hex(buf).toLowerCase() !== member.sha256.toLowerCase()) {
684	    throw bad('的 SHA-256 与内容不符');
685	  }
686	  return buf;
687	}
688	
689	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
690	async function atomicWrite(target, contents) {
691	  const dir = dirname(target);
692	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
693	  await writeFile(tmp, contents, { mode: 0o644 });
694	  try {
695	    await rename(tmp, target);
696	  } catch (err) {
697	    await rm(tmp, { force: true });
698	    throw err;
699	  }
700	}
