      '证明中的产物摘要与实际产物不一致（证明与产物无法对应）',
    );
  }
  if (sbom.artifactDigest.toLowerCase() !== digest.toLowerCase()) {
    throw new GateError(
      GATE_ERROR_KINDS.VERIFICATION,
      '软件物料清单的 artifactDigest 与实际产物不一致（SBOM 与产物无法对应）',
    );
  }

